using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.Rendering;using MiniErp.Models;using MiniErp.Security;using MiniErp.ViewModels;
namespace MiniErp.Controllers;
[Authorize(Roles=AppRoles.Administrator)] public class UsersController(UserManager<ApplicationUser> users):Controller { public IActionResult Index()=>View(users.Users.OrderBy(x=>x.Email).ToList()); [HttpGet] public IActionResult Create(){ViewBag.Roles=new SelectList(AppRoles.All);return View(new CreateUserViewModel());} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(CreateUserViewModel model){if(!AppRoles.All.Contains(model.Role))ModelState.AddModelError(nameof(model.Role),"Rol no válido.");if(!ModelState.IsValid){ViewBag.Roles=new SelectList(AppRoles.All,model.Role);return View(model);}var user=new ApplicationUser{UserName=model.Email,Email=model.Email,EmailConfirmed=true};var result=await users.CreateAsync(user,model.Password);if(result.Succeeded){await users.AddToRoleAsync(user,model.Role);return RedirectToAction(nameof(Index));}foreach(var error in result.Errors)ModelState.AddModelError(string.Empty,error.Description);ViewBag.Roles=new SelectList(AppRoles.All,model.Role);return View(model);} }
